      const body = new ReadableStream<Uint8Array>({
        start(c) {
          push = (chunk) => c.enqueue(chunk);
          end = () => c.close();
          init?.signal?.addEventListener("abort", () => { aborted = true; c.error(new DOMException("aborted", "AbortError")); });
